\title{Alexander-Polynomial Selection Rules for\\Angular Spectra of Knotted Light}
\author{Aristotle}
\date{July 18, 2026}

\begin{document}
\maketitle

\begin{abstract}
We study a spectral model for knotted optical fields in which an angular channel is selected when an equally spaced unit-circle phase is a zero of the knot's Alexander polynomial. For the prime two-strand torus-knot family $T(2,p)$, with $p$ an odd prime, the normalized Alexander polynomial is the cyclotomic polynomial $\Phi_{2p}$. On the $2p$-point phase grid, the index $l$ is therefore selected exactly when $\gcd(l,2p)=1$. The trefoil selects $l\equiv1,5\pmod6$, and the cinquefoil selects $l\equiv1,3,7,9\pmod {10}$. We give exact and numerical algorithms for generating these spectra. We also prove that the figure-eight polynomial $t^2-3t+1$ has no unit-circle roots and hence selects no channel on any angular grid. Its reciprocal real roots $(3\pm\sqrt5)/2$ cannot be converted into angular residues by reduction modulo one. This contrast separates angular information, carried by root arguments, from radial growth information, carried by root moduli. The results are conditional predictions of an Alexander-filter optical model rather than a derivation from electromagnetic field equations.
\end{abstract}

\section{Introduction}
Optical phase singularities are curves along which a complex wave amplitude vanishes. In three dimensions such a curve may close into a knot. This ``knotted light'' connects singular optics with low-dimensional topology: the field supplies a geometric knot, while knot polynomials offer algebraic summaries of its type.

An azimuthal mode with orbital-angular-momentum index $l$ has phase dependence $e^{il\theta}$. A finite angular sampling with $N$ positions therefore produces
\[
z_{N,l}=\exp(2\pi i l/N),\qquad l\in\Z.
\]
Suppose a transfer rule associated with a knot selects a phase precisely when it is a zero of an Alexander polynomial. This paper determines the exact consequences of that hypothesis. The prime two-strand torus knots yield modular-unit spectra. The figure-eight knot yields no angular channel at all, because its roots lie away from the unit circle.

The model is deliberately narrow. It does not assert that every knotted field realizes an Alexander-polynomial transfer function. A physical application requires a separately justified optical mechanism. The mathematical conclusions identify sharp predictions if such a filter is implemented.

\section{Mathematical and optical setting}

\begin{definition}[Angular phase grid]
For $N\ge1$ and $l\in\Z$, define
\[
z_{N,l}=e^{2\pi i l/N}.
\]
The value depends only on $l$ modulo $N$, and every grid point has modulus one.
\end{definition}

\begin{definition}[Alexander-selected spectrum]
For $A(t)\in\Z[t]$, define
\[
S_N(A)=\{l\in\{0,1,\ldots,N-1\}:A(z_{N,l})=0\}.
\]
For a knot polynomial this is interpreted as a model of selected orbital-angular-momentum residue classes.
\end{definition}

The Alexander polynomial is defined up to multiplication by $\pm t^m$. This ambiguity does not affect the selected set because every grid point is nonzero.

For odd $n\ge3$, use the normalized polynomial of $T(2,n)$
\[
A_n(t)=t^{n-1}-t^{n-2}+\cdots-t+1.
\]
The alternating sum telescopes to give
\[
(t+1)A_n(t)=t^n+1.
\]
When $p$ is an odd prime, cyclotomic factorization gives
\[
t^p+1=(t+1)\Phi_{2p}(t),
\qquad A_p(t)=\Phi_{2p}(t).
\]
The prime hypothesis is essential here: for composite odd $n$, the quotient generally splits into several cyclotomic factors.

\begin{definition}[Primitive root and modular unit]
A complex number $z$ is a primitive $N$th root of unity if its multiplicative order is exactly $N$. A residue $l$ modulo $N$ is a modular unit if it is invertible modulo $N$, equivalently if $\gcd(l,N)=1$.
\end{definition}

Every nonzero complex root $r$ has polar form $r=\rho e^{i\theta}$. Its argument is angular data, while $\rho$ is radial data. Only roots with $\rho=1$ can coincide with angular-grid points.

\section{Phase-grid lemmas}

\begin{lemma}[Grid generator]
For every $N\ge1$, $z_{N,1}$ is a primitive $N$th root of unity.
\end{lemma}
\begin{proof}
Its $N$th power is $e^{2\pi i}=1$. If a positive power $d<N$ were one, then $d/N$ would be an integer, which is impossible.
\end{proof}

\begin{lemma}[Power representation]
For every $l\in\Z$, $z_{N,l}=z_{N,1}^{\,l}$.
\end{lemma}
\begin{proof}
This is the exponential identity $e^{la}=(e^a)^l$ with $a=2\pi i/N$.
\end{proof}

\begin{lemma}[Primitive-power criterion]
If $\zeta$ is a primitive $N$th root, then $\zeta^l$ is primitive of order $N$ if and only if $\gcd(l,N)=1$.
\end{lemma}
\begin{proof}
The order of $\zeta^l$ is $N/\gcd(l,N)$: the least positive $m$ for which $N$ divides $lm$ is $N/\gcd(l,N)$. This order equals $N$ precisely under coprimality.
\end{proof}

\section{Prime torus-knot selection}

\begin{theorem}[Primitive-root characterization]
Let $p$ be an odd prime. Then $A_p(z_{2p,l})=0$ if and only if $z_{2p,l}$ is a primitive $2p$th root of unity.
\end{theorem}
\begin{proof}
Since $A_p=\Phi_{2p}$, its roots are exactly the primitive $2p$th roots.
\end{proof}

\begin{theorem}[Exact coprimality selection rule]
Let $p$ be an odd prime. Then
\[
A_p(z_{2p,l})=0\quad\Longleftrightarrow\quad\gcd(l,2p)=1.
\]
Consequently,
\[
S_{2p}(A_p)=\{l:0\le l<2p,\ \gcd(l,2p)=1\}.
\]
\end{theorem}
\begin{proof}
The preceding theorem converts vanishing into primitivity. The grid generator is primitive, the $l$th phase is its $l$th power, and the primitive-power criterion converts primitivity into coprimality.
\end{proof}

\begin{corollary}[Channel count]
For odd prime $p$, $|S_{2p}(A_p)|=\varphi(2p)=p-1$.
\end{corollary}
\begin{proof}
The selected set is the unit group $\units{2p}$, whose cardinality is $\varphi(2p)$. Multiplicativity of the totient gives $\varphi(2p)=p-1$.
\end{proof}

\begin{corollary}[Periodicity and conjugation]
Selection depends only on $l$ modulo $2p$. If $l$ is selected, then $2p-l$ is selected, and the corresponding phases are complex conjugates.
\end{corollary}
\begin{proof}
Coprimality is periodic and preserved by negation, while $z_{2p,-l}=\overline{z_{2p,l}}$.
\end{proof}

The selected phases form the full set of primitive $2p$th roots and are permuted transitively by exponentiation with elements of $\units{2p}$. Thus the channels carry Galois and modular-group structure.

\section{Trefoil and cinquefoil}

For the trefoil $T(2,3)$,
\[
A_3(t)=t^2-t+1=\Phi_6(t).
\]
\begin{theorem}[Trefoil spectrum]
In one period,
\[
A_3(z_{6,l})=0\quad\Longleftrightarrow\quad l\in\{1,5\}.
\]
Hence $l\equiv1,5\pmod6$.
\end{theorem}
\begin{proof}
The selected residues are exactly those coprime to $6$, namely $1$ and $5$.
\end{proof}

For the cinquefoil $T(2,5)$,
\[
A_5(t)=t^4-t^3+t^2-t+1=\Phi_{10}(t).
\]
\begin{theorem}[Cinquefoil spectrum]
In one period,
\[
A_5(z_{10,l})=0\quad\Longleftrightarrow\quad l\in\{1,3,7,9\}.
\]
Hence $l\equiv1,3,7,9\pmod {10}$.
\end{theorem}
\begin{proof}
These and only these residues are coprime to $10$.
\end{proof}

\section{Figure-eight exclusion and the unknot}
The figure-eight polynomial is
\[
F(t)=t^2-3t+1,
\]
with reciprocal positive roots
\[
r_\pm=\frac{3\pm\sqrt5}{2}.
\]
One root lies outside and one inside the unit circle.

\begin{theorem}[Figure-eight unit-circle exclusion]
If $z\in\C$ and $|z|=1$, then $z^2-3z+1\ne0$.
\end{theorem}
\begin{proof}
If the polynomial vanished, division by nonzero $z$ would give $z+z^{-1}=3$. On the unit circle $z^{-1}=\overline z$, so $2\operatorname{Re}(z)=3$. But $|\operatorname{Re}(z)|\le1$, a contradiction.
\end{proof}

\begin{corollary}[No figure-eight angular-grid channel]
For every $N\ge1$ and $l\in\Z$, $F(z_{N,l})\ne0$.
\end{corollary}
\begin{proof}
Every angular phase has modulus one.
\end{proof}

Reducing $r_\pm$ modulo one does not repair the failure: $F(r)=0$ does not imply $F(e^{2\pi i(r\bmod1)})=0$. Root modulus and root argument are different observables.

The unknot has constant Alexander polynomial $1$, so $S_N(1)=\varnothing$ for every $N$. If a baseline $l=0$ channel is desired, it must be introduced as an independent optical convention.

\section{Algorithms and numerical demonstrations}

\begin{algorithm}[Modular-unit spectrum generator]
Given an odd prime $p$, set $N=2p$. For each $l=0,\ldots,N-1$, compute $\gcd(l,N)$ by the Euclidean algorithm and retain $l$ exactly when the result is one. Return the retained list.
\end{algorithm}
The scan uses $O(N\log N)$ elementary arithmetic steps in a simple model and output space $O(\varphi(N))$. It is exact and avoids floating-point complex evaluation.

\begin{algorithm}[Complex phase-grid residual scan]
Given coefficients $a_0,\ldots,a_d$, grid size $N$, and tolerance $\varepsilon$, compute $z_{N,l}$ for each index, evaluate $A(z_{N,l})$ by Horner's rule, and record the index when $|A(z_{N,l})|<\varepsilon$.
\end{algorithm}
This costs $O(Nd)$ complex operations. It demonstrates the cancellation but should be compared with the exact arithmetic prediction whenever available.

\begin{algorithm}[Angular-versus-radial root classifier]
For each polynomial root $r$, compute $\rho=|r|$ and $\theta=\arg r$. If $|\rho-1|$ is below a chosen tolerance, report the angular fraction $\theta/(2\pi)$ modulo one. Otherwise report the radial logarithmic rate $\log\rho$. For reciprocal polynomials, pair roots and test cancellation of the rates.
\end{algorithm}

The trefoil scan produces numerical zeros only at $1$ and $5$ on the six-point grid. The cinquefoil scan produces zeros only at $1,3,7,9$ on the ten-point grid. A figure-eight scan on every finite grid produces no exact zero; this persists under refinement by the exclusion theorem. Its radial rates are
\[
\lambda_\pm=\log r_\pm=\pm\log\left(\frac{3+\sqrt5}{2}\right).
\]
Writing $\phi=(1+\sqrt5)/2$ gives $\lambda_+=2\log\phi$.

\section{Applications and interpretation}
Within $T(2,p)$ for odd primes, the period $2p$ and channel count $p-1$ each recover $p$. Thus an observed modular-unit spectrum determines the family parameter, assuming the transfer model and family membership. This is not a universal knot classifier: Alexander polynomials are not complete invariants.

The arithmetic rule supplies robust consistency checks. Predicted channels occur in conjugate pairs and are permuted by modular units. Noise affects measured amplitudes, but these discrete symmetries can diagnose missing or spurious channels.

Off-circle roots motivate radial spectroscopy. For a monic polynomial $A(t)=\prod_j(t-r_j)$, the logarithmic Mahler measure is
\[
m(A)=\sum_j\log\max(1,|r_j|).
\]
Cyclotomic prime torus polynomials have $m(A_p)=0$, whereas
\[
m(F)=\log\left(\frac{3+\sqrt5}{2}\right)=2\log\phi.
\]
This suggests an aggregate radial-growth observable complementary to angular momentum.

An experimental implementation would need a transfer element whose coherent response contains $A(e^{i\theta})$, perhaps through interferometric paths encoding polynomial coefficients and powers of the phase. OAM-resolved detection could then test support at the predicted residues. Such an implementation is an engineering hypothesis, not a consequence of knot topology alone.

\section{Limitations}
The results analyze an Alexander phase-filter model and do not derive it from Maxwell's equations. A phase singularity tracing a knot does not automatically determine OAM amplitudes. Alexander polynomials are not complete knot invariants. The natural grid in the prime theorem has size $2p$, the cyclotomic order, rather than the crossing number $p$. The prime assumption is necessary for a single cyclotomic factor; composite parameters require divisor strata. Finally, real roots cannot be converted into angular channels by reducing their numerical values modulo one.

\section{Future work}
For composite odd $n$, the identity $(t+1)A_n(t)=t^n+1$ suggests a decomposition into primitive $2d$th-root strata indexed by divisors of $n$. Products of prime optical filters invite a Chinese-remainder analysis because phase multiplication adds angular indices while each prime spectrum is a modular unit group.

For off-circle roots, radial propagation should be modeled explicitly. The figure-eight rates $\pm2\log\phi$ provide a direct target, while Mahler measure may summarize total radial instability. Inverse reconstruction under realistic noise is another priority: conjugate pairing and unit-group symmetry may act as error-detecting constraints.

\section{Conclusion}
For prime torus knots $T(2,p)$, Alexander selection on the natural $2p$-point phase grid is exactly modular coprimality. The trefoil spectrum is $\{1,5\}$ modulo $6$, and the cinquefoil spectrum is $\{1,3,7,9\}$ modulo $10$. The figure-eight polynomial has no unit-circle roots and therefore no selected angular-grid phase. Its reciprocal roots instead carry radial magnitude. A viable spectroscopy of knotted light should distinguish root arguments, which are angular, from root moduli, which describe growth and decay.

