from __future__ import annotations
import cmath, math

def minimum_residual(n: int) -> tuple[int, float]:
    """Find the smallest figure-eight residual on an n-point phase grid."""
    values = []
    for l in range(n):
        z = cmath.exp(2j * math.pi * l / n)
        values.append((l, abs(z*z - 3*z + 1)))
    return min(values, key=lambda pair: pair[1])

for size in (6, 10, 32, 128):
    l, residual = minimum_residual(size)
    print(f"N={size}: minimum |F(z)|={residual:.9f} at l={l}; no zero")
    assert residual > 0.9

