from __future__ import annotations
import cmath, math
from typing import Iterable

def classify_roots(roots: Iterable[complex], tolerance: float = 1e-8) -> list[dict[str, float | str]]:
    """Separate unit-circle angular data from off-circle radial rates."""
    output: list[dict[str, float | str]] = []
    for root in roots:
        modulus = abs(root)
        if abs(modulus - 1.0) < tolerance:
            output.append({"kind": "angular", "turns": (cmath.phase(root)/(2*math.pi)) % 1.0})
        else:
            output.append({"kind": "radial", "log_rate": math.log(modulus)})
    return output

